def find_min_index(numbers):
    """
    This function takes a list of numbers as input and returns the index of the minimum value in the list.

    Parameters:
    numbers (list): A list of numbers.

    Returns:
    int: The index of the minimum value in the list.
    """
    if not numbers:
        return None
    else:
        return numbers.index(min(numbers))

