class SuffixTreeNode:
    def __init__(self, char):
        self.char = char
        self.children = {}
        self.indexes = []

    def insert(self, word, index):
        if not word:
            return
        char = word[0]
        if char not in self.children:
            self.children[char] = SuffixTreeNode(char)
        self.children[char].indexes.append(index)
        self.children[char].insert(word[1:], index)

    def search(self, word):
        if not word:
            return self.indexes
        char = word[0]
        if char not in self.children:
            return []
        return self.children[char].search(word[1:])


class SuffixTree:
    def __init__(self, text):
        self.root = SuffixTreeNode("")
        for i in range(len(text)):
            self.root.insert(text[i:], i)

    def find_occurrences(self, word):
        return self.root.search(word)

    def print_occurrences(self, word):
        occurs = self.find_occurrences(word)
        if occurs:
            print(f"The word '{word}' occurs at the following indexes:")
            for index in occurs:
                print(index)
        else:
            print(f"The word '{word}' does not occur in the text.")


